import numpy as np, torch, model
net=model.load(); w=torch.tensor(np.load('contrast_c1_blocks.1.act_k13.npy')); b=-17.0692
torch.manual_seed(1); N=4096
xi=torch.randn(N,2); c=torch.rand(N)
R=torch.tensor([[0.,-1.],[1.,0.]])
def run(s, thr, k0=10,k1=14):
    x=xi.clone(); fires=[]
    for k in range(20):
        t=torch.full((N,),1-k/20)
        v,a=net.velocity(x,t,c,('blocks.1.act',),count=False)
        sc=a['blocks.1.act']@w+b; fires.append(sc)
        if s and k0<=k<k1: v=v+s*(x@R.T)*(sc>thr)[:,None].float()
        x=x-v/20
    return x,torch.stack(fires)
with torch.no_grad():
    a0,F0=run(0,0); lab=(F0[13]>0)
    lab2=(F0[16]>0)|(F0[13]>0)
    for thr in [0,2,4,6]:
      for s in [6,8]:
        for kk in [(10,14),(11,14)]:
            a1,_=run(s,thr,*kk); mv=(a1-a0).norm(dim=1)
            print(thr,s,kk,'tgt moved>0.5',(mv[lab]>0.5).float().mean().item(),'nontgt moved>0.3',(mv[~lab2]>0.3).float().mean().item())

import numpy as np, torch, model
from scipy.spatial import cKDTree
net=model.load(); w=torch.tensor(np.load('contrast_c2_blocks.2.act_k12.npy')); b=-7.5865
xi=torch.tensor(np.load('my_xi.npy'))[:2048]; c=torch.tensor(np.load('my_c.npy'))[:2048]
a0=np.load('my_a.npy'); c0=np.load('my_c.npy'); tg=np.load('my_tgt.npy')
tree=cKDTree(np.c_[a0,3*c0]); 
def run(delta,lo,hi):
    x=xi.clone()
    for k in range(20):
        t=torch.full((len(x),),1-k/20)
        v,A=net.velocity(x,t,c,("blocks.2.act",),count=True)
        if lo<=k<hi:
            f=(A["blocks.2.act"]@w+b)>0
            v=v+f.float()[:,None]*torch.tensor(delta,dtype=torch.float32)
        x=x-v/20
    return x.numpy()
T=tg[:2048]; A0=a0[:2048]
def score(a):
    dd,j=tree.query(np.c_[a,3*c0[:2048]])
    bad=tg[j]
    resc=(~bad[T]&(dd[T]<0.4)).mean()
    mv=np.linalg.norm(a-A0,axis=1)
    drift=(mv[~T]>0.3).mean()
    off=(dd>0.4).mean()
    return resc,drift,off
res=[]
for lo,hi in [(0,4),(0,8),(4,10),(8,13)]:
  for ang in range(0,360,45):
    for mag in [3,6,10]:
      d=[mag*np.cos(np.radians(ang)),mag*np.sin(np.radians(ang))]
      s=score(run(d,lo,hi)); res.append((s[0]-s[1]-s[2],lo,hi,ang,mag)+tuple(np.round(s,3)))
res.sort(reverse=True)
for r in res[:15]: print(r)
